package approval

import (
	"context"
	"strings"
)

// Choice is the bounded decision a messaging-platform approval button may
// resolve for a pending gateway approval request.
type Choice string

const (
	ChoiceOnce    Choice = "once"
	ChoiceSession Choice = "session"
	ChoiceAlways  Choice = "always"
	ChoiceDeny    Choice = "deny"
)

// Resolution is the redacted evidence passed from channel callbacks into the
// gateway approval store/resolver.
type Resolution struct {
	SessionKey string
	Choice     Choice
	Platform   string
	ChatID     string
	MessageID  string
	ActorID    string
	Evidence   map[string]string
}

// Resolver owns the gateway-side approval state for pending dangerous
// operations. Channel implementations call it after a user chooses a bounded
// approval action.
type Resolver interface {
	ResolveGatewayApproval(context.Context, Resolution) error
}

// ResolverFunc adapts a function to Resolver.
type ResolverFunc func(context.Context, Resolution) error

func (f ResolverFunc) ResolveGatewayApproval(ctx context.Context, res Resolution) error {
	if f == nil {
		return nil
	}
	return f(ctx, res)
}

// ParseChoice normalizes a gateway approval decision label.
func ParseChoice(value string) (Choice, bool) {
	switch strings.ToLower(strings.TrimSpace(value)) {
	case string(ChoiceOnce):
		return ChoiceOnce, true
	case string(ChoiceSession):
		return ChoiceSession, true
	case string(ChoiceAlways):
		return ChoiceAlways, true
	case string(ChoiceDeny):
		return ChoiceDeny, true
	default:
		return "", false
	}
}

func validChoice(choice Choice) bool {
	switch choice {
	case ChoiceOnce, ChoiceSession, ChoiceAlways, ChoiceDeny:
		return true
	default:
		return false
	}
}

package approval

import (
	"context"
	"errors"
	"strings"
	"sync"

	"github.com/TrebuchetDynamics/gormes-agent/internal/gateway/mapclone"
)

var (
	ErrGatewayApprovalEmptySession  = errors.New("gateway approval session key is empty")
	ErrGatewayApprovalInvalidChoice = errors.New("gateway approval choice is invalid")
	ErrGatewayApprovalNotPending    = errors.New("gateway approval is not pending")
)

// GatewayApprovalRequest is the dangerous operation metadata queued while a
// gateway user chooses once/session/always/deny.
type GatewayApprovalRequest struct {
	Command     string
	Description string
	PatternKey  string
	PatternKeys []string
	Evidence    map[string]string
}

// GatewayApprovalTicket identifies one queued approval request.
type GatewayApprovalTicket struct {
	SessionKey string
	ID         uint64
}

// GatewayApprovalOutcome records the decision applied to a queued request.
type GatewayApprovalOutcome struct {
	Ticket     GatewayApprovalTicket
	Request    GatewayApprovalRequest
	Resolution Resolution
	Choice     Choice
	Canceled   bool
}

// GatewayApprovalQueue stores pending approval requests per gateway session.
// It mirrors Hermes' FIFO gateway approval queue without doing any channel IO.
type GatewayApprovalQueue struct {
	mu       sync.Mutex
	nextID   uint64
	queues   map[string][]*gatewayApprovalEntry
	outcomes map[uint64]GatewayApprovalOutcome
}

type gatewayApprovalEntry struct {
	ticket  GatewayApprovalTicket
	request GatewayApprovalRequest
}

func NewGatewayApprovalQueue() *GatewayApprovalQueue {
	return &GatewayApprovalQueue{
		queues:   map[string][]*gatewayApprovalEntry{},
		outcomes: map[uint64]GatewayApprovalOutcome{},
	}
}

func (q *GatewayApprovalQueue) SubmitGatewayApproval(sessionKey string, req GatewayApprovalRequest) (GatewayApprovalTicket, error) {
	sessionKey = strings.TrimSpace(sessionKey)
	if sessionKey == "" {
		return GatewayApprovalTicket{}, ErrGatewayApprovalEmptySession
	}
	if q == nil {
		return GatewayApprovalTicket{}, ErrGatewayApprovalNotPending
	}

	q.mu.Lock()
	defer q.mu.Unlock()
	q.ensureLocked()
	q.nextID++
	ticket := GatewayApprovalTicket{SessionKey: sessionKey, ID: q.nextID}
	q.queues[sessionKey] = append(q.queues[sessionKey], &gatewayApprovalEntry{
		ticket:  ticket,
		request: cloneGatewayApprovalRequest(req),
	})
	return ticket, nil
}

func (q *GatewayApprovalQueue) HasBlockingApproval(sessionKey string) bool {
	sessionKey = strings.TrimSpace(sessionKey)
	if sessionKey == "" || q == nil {
		return false
	}

	q.mu.Lock()
	defer q.mu.Unlock()
	return len(q.queues[sessionKey]) > 0
}

func (q *GatewayApprovalQueue) ResolveGatewayApproval(_ context.Context, res Resolution) error {
	sessionKey := strings.TrimSpace(res.SessionKey)
	if sessionKey == "" {
		return ErrGatewayApprovalEmptySession
	}
	if !validChoice(res.Choice) {
		return ErrGatewayApprovalInvalidChoice
	}
	if q == nil {
		return ErrGatewayApprovalNotPending
	}

	q.mu.Lock()
	defer q.mu.Unlock()
	q.ensureLocked()
	queue := q.queues[sessionKey]
	if len(queue) == 0 {
		return ErrGatewayApprovalNotPending
	}
	entry := queue[0]
	queue = queue[1:]
	if len(queue) == 0 {
		delete(q.queues, sessionKey)
	} else {
		q.queues[sessionKey] = queue
	}
	q.recordOutcomeLocked(entry, res, false)
	return nil
}

func (q *GatewayApprovalQueue) ResolveAllGatewayApprovals(sessionKey string, choice Choice) (int, error) {
	sessionKey = strings.TrimSpace(sessionKey)
	if sessionKey == "" {
		return 0, ErrGatewayApprovalEmptySession
	}
	if !validChoice(choice) {
		return 0, ErrGatewayApprovalInvalidChoice
	}
	if q == nil {
		return 0, nil
	}

	q.mu.Lock()
	defer q.mu.Unlock()
	q.ensureLocked()
	entries := q.queues[sessionKey]
	if len(entries) == 0 {
		return 0, nil
	}
	delete(q.queues, sessionKey)
	for _, entry := range entries {
		q.recordOutcomeLocked(entry, Resolution{SessionKey: sessionKey, Choice: choice}, false)
	}
	return len(entries), nil
}

func (q *GatewayApprovalQueue) ClearGatewayApprovalSession(sessionKey string) int {
	sessionKey = strings.TrimSpace(sessionKey)
	if sessionKey == "" || q == nil {
		return 0
	}

	q.mu.Lock()
	defer q.mu.Unlock()
	q.ensureLocked()
	entries := q.queues[sessionKey]
	if len(entries) == 0 {
		return 0
	}
	delete(q.queues, sessionKey)
	for _, entry := range entries {
		q.recordOutcomeLocked(entry, Resolution{SessionKey: sessionKey, Choice: ChoiceDeny}, true)
	}
	return len(entries)
}

func (q *GatewayApprovalQueue) GatewayApprovalOutcome(ticket GatewayApprovalTicket) (GatewayApprovalOutcome, bool) {
	if q == nil || ticket.ID == 0 || strings.TrimSpace(ticket.SessionKey) == "" {
		return GatewayApprovalOutcome{}, false
	}

	q.mu.Lock()
	defer q.mu.Unlock()
	outcome, ok := q.outcomes[ticket.ID]
	if !ok || outcome.Ticket.SessionKey != ticket.SessionKey {
		return GatewayApprovalOutcome{}, false
	}
	return cloneGatewayApprovalOutcome(outcome), true
}

func (q *GatewayApprovalQueue) ensureLocked() {
	if q.queues == nil {
		q.queues = map[string][]*gatewayApprovalEntry{}
	}
	if q.outcomes == nil {
		q.outcomes = map[uint64]GatewayApprovalOutcome{}
	}
}

func (q *GatewayApprovalQueue) recordOutcomeLocked(entry *gatewayApprovalEntry, res Resolution, canceled bool) {
	choice := res.Choice
	if choice == "" {
		choice = ChoiceDeny
	}
	q.outcomes[entry.ticket.ID] = GatewayApprovalOutcome{
		Ticket:     entry.ticket,
		Request:    cloneGatewayApprovalRequest(entry.request),
		Resolution: cloneResolution(res),
		Choice:     choice,
		Canceled:   canceled,
	}
}

func cloneGatewayApprovalRequest(req GatewayApprovalRequest) GatewayApprovalRequest {
	req.PatternKeys = append([]string(nil), req.PatternKeys...)
	req.Evidence = cloneStringMap(req.Evidence)
	return req
}

func cloneResolution(res Resolution) Resolution {
	res.Evidence = cloneStringMap(res.Evidence)
	return res
}

func cloneStringMap(input map[string]string) map[string]string {
	return mapclone.StringString(input)
}

func cloneGatewayApprovalOutcome(outcome GatewayApprovalOutcome) GatewayApprovalOutcome {
	outcome.Request = cloneGatewayApprovalRequest(outcome.Request)
	outcome.Resolution = cloneResolution(outcome.Resolution)
	return outcome
}

package approval

import (
	"context"
	"testing"
)

func TestParseChoice(t *testing.T) {
	tests := []struct {
		value string
		want  Choice
		ok    bool
	}{
		{value: "once", want: ChoiceOnce, ok: true},
		{value: " SESSION ", want: ChoiceSession, ok: true},
		{value: "always", want: ChoiceAlways, ok: true},
		{value: "deny", want: ChoiceDeny, ok: true},
		{value: "approved", ok: false},
		{value: "", ok: false},
	}

	for _, tt := range tests {
		t.Run(tt.value, func(t *testing.T) {
			got, ok := ParseChoice(tt.value)
			if ok != tt.ok {
				t.Fatalf("ok = %v, want %v", ok, tt.ok)
			}
			if got != tt.want {
				t.Fatalf("choice = %q, want %q", got, tt.want)
			}
		})
	}
}

func TestResolverFunc(t *testing.T) {
	var got Resolution
	resolver := ResolverFunc(func(_ context.Context, res Resolution) error {
		got = res
		return nil
	})

	err := resolver.ResolveGatewayApproval(context.Background(), Resolution{
		SessionKey: "slack:C123:sess-1",
		Choice:     ChoiceOnce,
		Platform:   "slack",
		ChatID:     "C123",
		MessageID:  "1711111111.000100",
		ActorID:    "U42",
	})
	if err != nil {
		t.Fatalf("ResolveGatewayApproval: %v", err)
	}
	if got.SessionKey != "slack:C123:sess-1" || got.Choice != ChoiceOnce || got.Platform != "slack" {
		t.Fatalf("resolution = %+v, want Slack once resolution", got)
	}
}

package approval

import (
	"context"
	"errors"
	"testing"
)

func TestApprovalQueueSubmitAndHasBlocking(t *testing.T) {
	q := NewGatewayApprovalQueue()

	ticket, err := q.SubmitGatewayApproval("session-a", GatewayApprovalRequest{
		Command:     "git reset --hard",
		Description: "destructive git reset",
		PatternKeys: []string{
			"git reset --hard",
		},
		Evidence: map[string]string{"detector": "dangerous"},
	})
	if err != nil {
		t.Fatalf("SubmitGatewayApproval: %v", err)
	}
	if ticket.SessionKey != "session-a" || ticket.ID == 0 {
		t.Fatalf("ticket = %+v, want session-a with nonzero ID", ticket)
	}
	if !q.HasBlockingApproval("session-a") {
		t.Fatal("HasBlockingApproval(session-a) = false, want true")
	}
	if q.HasBlockingApproval("session-b") {
		t.Fatal("HasBlockingApproval(session-b) = true, want false")
	}
}

func TestApprovalQueueClonesRequestEvidence(t *testing.T) {
	q := NewGatewayApprovalQueue()
	evidence := map[string]string{"detector": "original"}
	ticket, err := q.SubmitGatewayApproval("session-a", GatewayApprovalRequest{Command: "danger", Evidence: evidence})
	if err != nil {
		t.Fatalf("SubmitGatewayApproval: %v", err)
	}
	evidence["detector"] = "mutated"

	if err := q.ResolveGatewayApproval(context.Background(), Resolution{SessionKey: "session-a", Choice: ChoiceOnce}); err != nil {
		t.Fatalf("ResolveGatewayApproval: %v", err)
	}
	outcome, ok := q.GatewayApprovalOutcome(ticket)
	if !ok {
		t.Fatal("approval outcome missing")
	}
	outcome.Request.Evidence["detector"] = "caller-mutated"

	stored, ok := q.GatewayApprovalOutcome(ticket)
	if !ok {
		t.Fatal("approval outcome missing on second read")
	}
	if got := stored.Request.Evidence["detector"]; got != "original" {
		t.Fatalf("stored evidence detector = %q, want original", got)
	}
}

func TestApprovalQueueResolveOldestFIFO(t *testing.T) {
	q := NewGatewayApprovalQueue()
	first, err := q.SubmitGatewayApproval("session-a", GatewayApprovalRequest{Command: "first"})
	if err != nil {
		t.Fatalf("Submit first: %v", err)
	}
	second, err := q.SubmitGatewayApproval("session-a", GatewayApprovalRequest{Command: "second"})
	if err != nil {
		t.Fatalf("Submit second: %v", err)
	}

	err = q.ResolveGatewayApproval(context.Background(), Resolution{
		SessionKey: "session-a",
		Choice:     ChoiceSession,
	})
	if err != nil {
		t.Fatalf("ResolveGatewayApproval: %v", err)
	}

	firstOutcome, ok := q.GatewayApprovalOutcome(first)
	if !ok {
		t.Fatal("first outcome missing")
	}
	if firstOutcome.Request.Command != "first" || firstOutcome.Choice != ChoiceSession || firstOutcome.Canceled {
		t.Fatalf("first outcome = %+v, want session approval for first request", firstOutcome)
	}
	if _, ok := q.GatewayApprovalOutcome(second); ok {
		t.Fatal("second request resolved too early; want FIFO single resolution")
	}
	if !q.HasBlockingApproval("session-a") {
		t.Fatal("HasBlockingApproval(session-a) = false after resolving one of two, want true")
	}
}

func TestApprovalQueueResolveAll(t *testing.T) {
	q := NewGatewayApprovalQueue()
	first, err := q.SubmitGatewayApproval("session-a", GatewayApprovalRequest{Command: "first"})
	if err != nil {
		t.Fatalf("Submit first: %v", err)
	}
	second, err := q.SubmitGatewayApproval("session-a", GatewayApprovalRequest{Command: "second"})
	if err != nil {
		t.Fatalf("Submit second: %v", err)
	}
	other, err := q.SubmitGatewayApproval("session-b", GatewayApprovalRequest{Command: "other"})
	if err != nil {
		t.Fatalf("Submit other: %v", err)
	}

	count, err := q.ResolveAllGatewayApprovals("session-a", ChoiceAlways)
	if err != nil {
		t.Fatalf("ResolveAllGatewayApprovals: %v", err)
	}
	if count != 2 {
		t.Fatalf("resolved count = %d, want 2", count)
	}
	for _, ticket := range []GatewayApprovalTicket{first, second} {
		outcome, ok := q.GatewayApprovalOutcome(ticket)
		if !ok {
			t.Fatalf("outcome for ticket %+v missing", ticket)
		}
		if outcome.Choice != ChoiceAlways || outcome.Canceled {
			t.Fatalf("outcome = %+v, want always approval", outcome)
		}
	}
	if q.HasBlockingApproval("session-a") {
		t.Fatal("session-a still blocking after resolve all")
	}
	if !q.HasBlockingApproval("session-b") {
		t.Fatal("session-b not blocking; resolve all must not affect other sessions")
	}
	if _, ok := q.GatewayApprovalOutcome(other); ok {
		t.Fatal("session-b outcome exists; resolve all touched the wrong session")
	}
}

func TestApprovalQueueClearSessionCancelsPending(t *testing.T) {
	q := NewGatewayApprovalQueue()
	first, err := q.SubmitGatewayApproval("session-a", GatewayApprovalRequest{Command: "first"})
	if err != nil {
		t.Fatalf("Submit first: %v", err)
	}
	second, err := q.SubmitGatewayApproval("session-a", GatewayApprovalRequest{Command: "second"})
	if err != nil {
		t.Fatalf("Submit second: %v", err)
	}

	count := q.ClearGatewayApprovalSession("session-a")
	if count != 2 {
		t.Fatalf("clear count = %d, want 2", count)
	}
	if q.HasBlockingApproval("session-a") {
		t.Fatal("session-a still blocking after clear")
	}
	for _, ticket := range []GatewayApprovalTicket{first, second} {
		outcome, ok := q.GatewayApprovalOutcome(ticket)
		if !ok {
			t.Fatalf("outcome for ticket %+v missing", ticket)
		}
		if outcome.Choice != ChoiceDeny || !outcome.Canceled {
			t.Fatalf("outcome = %+v, want canceled deny", outcome)
		}
	}
}

func TestApprovalQueueInvalidChoiceAndEmptySessionFailClosed(t *testing.T) {
	q := NewGatewayApprovalQueue()
	if _, err := q.SubmitGatewayApproval("", GatewayApprovalRequest{Command: "missing session"}); !errors.Is(err, ErrGatewayApprovalEmptySession) {
		t.Fatalf("SubmitGatewayApproval empty session error = %v, want ErrGatewayApprovalEmptySession", err)
	}
	if err := q.ResolveGatewayApproval(context.Background(), Resolution{SessionKey: "session-a", Choice: Choice("bad")}); !errors.Is(err, ErrGatewayApprovalInvalidChoice) {
		t.Fatalf("ResolveGatewayApproval invalid choice error = %v, want ErrGatewayApprovalInvalidChoice", err)
	}
	if _, err := q.ResolveAllGatewayApprovals("session-a", Choice("bad")); !errors.Is(err, ErrGatewayApprovalInvalidChoice) {
		t.Fatalf("ResolveAllGatewayApprovals invalid choice error = %v, want ErrGatewayApprovalInvalidChoice", err)
	}
	if err := q.ResolveGatewayApproval(context.Background(), Resolution{SessionKey: "", Choice: ChoiceOnce}); !errors.Is(err, ErrGatewayApprovalEmptySession) {
		t.Fatalf("ResolveGatewayApproval empty session error = %v, want ErrGatewayApprovalEmptySession", err)
	}
	if err := q.ResolveGatewayApproval(context.Background(), Resolution{SessionKey: "session-a", Choice: ChoiceOnce}); !errors.Is(err, ErrGatewayApprovalNotPending) {
		t.Fatalf("ResolveGatewayApproval missing pending error = %v, want ErrGatewayApprovalNotPending", err)
	}
	if count, err := q.ResolveAllGatewayApprovals("session-a", ChoiceOnce); err != nil || count != 0 {
		t.Fatalf("ResolveAllGatewayApprovals missing pending = (%d, %v), want (0, nil)", count, err)
	}
	if count := q.ClearGatewayApprovalSession(""); count != 0 {
		t.Fatalf("ClearGatewayApprovalSession empty session = %d, want 0", count)
	}
}

